import unittest

class Test(unittest.TestCase):
    def test_found_middle(self):
        self.assertEqual(binary_search([1,3,5,7,9,11], 7), 3)
    def test_found_first(self):
        self.assertEqual(binary_search([2,4,6], 2), 0)
